import{_ as d,C as l,o,c as r,ah as a,E as i}from"./chunks/framework.DuX8SFU5.js";const A=JSON.parse('{"title":"AM_CAN_LOGGER — регистратор CAN-трафика и вибраций","description":"","frontmatter":{"title":"AM_CAN_LOGGER — регистратор CAN-трафика и вибраций","device":{"name":"AM_CAN_LOGGER","title":"Регистратор CAN-трафика и вибраций","summary":"Автономно записывает CAN-шины машины и вибрации на карту памяти. Ставится силами площадки, ничего не передаёт в шины, по светодиоду видно, идёт ли запись.","status":"prototype","image":"am_can_logger_enclosure.webp","specs":["2 шины CAN","только приём","автоподбор скорости","выгрузка в candump","вибрации, IMU","веб-панель"],"order":3},"pdf":"/pdf/AM_CAN_LOGGER_overview.pdf"},"headers":[],"relativePath":"am_can_logger/index.md","filePath":"am_can_logger/README.md"}'),n={name:"am_can_logger/index.md"};function c(h,t,_,s,p,u){const e=l("AssetImage");return o(),r("div",null,[t[0]||(t[0]=a('<h2 id="зачем" tabindex="-1">Зачем <a class="header-anchor" href="#зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><p>Регистратор даёт полную запись работы машины: что делал оператор и как отвечала машина. Записываются сырые кадры всех подключённых CAN-шин, без расшифровки на устройстве: словарь сигналов можно уточнять потом и перечитывать им уже снятые записи. Вместе с CAN пишутся вибрации, чтобы связывать их с режимами работы машины.</p><h2 id="как-работает" tabindex="-1">Как работает <a class="header-anchor" href="#как-работает" aria-label="Permalink to &quot;Как работает&quot;">​</a></h2><ul><li>При подаче питания регистратор стартует сам, без ноутбука и настройки на месте.</li><li>Он слушает две шины CAN в режиме только приёма: не подтверждает кадры и не выдаёт ошибок, поэтому не влияет на штатную сеть.</li><li>Скорость каждой шины задаётся настройкой или определяется автоматически. Автоподбор тоже только слушает: на неверной скорости кадры не проходят проверку, поэтому шина ничего не замечает, а запись начинается, как только скорость найдена, обычно в пределах секунды.</li><li>Каждый кадр с меткой времени записывается на карту microSD в компактном двоичном виде, втрое меньше текстового; при выгрузке запись превращается в стандартный формат <code>candump</code>.</li><li>Новый файл начинается каждые 10 минут, а открытый файл сбрасывается на карту раз в секунду, так что при пропадании питания теряется около последней секунды.</li><li>Сырые данные акселерометра и гироскопа для анализа вибраций включаются в настройках: они делят пропускную способность карты с CAN.</li><li>Потери кадров считаются по каждой шине, раз в секунду пишутся в журнал и видны в панели.</li><li>Перед действием на машине («начало бурения», «замена штанги») в панели ставится текстовая отметка: она ложится в запись рядом с кадрами, на тех же часах.</li></ul><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><p>Подробная инструкция — в <a href="./user-guide">руководстве пользователя</a>.</p><p>Регистратор ставит механик или инженер площадки по инструкции, без участия разработчиков.</p><ul><li>Подключение к шине — через переходной жгут с обеими половинами штатного разъёма, без разрезания проводки машины.</li><li>Собственный терминатор 120 Ом регистратора отключён: у существующей шины терминация уже есть.</li><li>Питание — от бортовой сети через преобразователь и предохранитель.</li><li>Место — в кабине: там теплее, чем в наружных шкафах, а карта памяти должна быть доступна без разборки панелей.</li></ul><p>В конце смены карта памяти снимается и передаётся на обработку; сеть для работы регистратора не нужна.</p><h2 id="индикация" tabindex="-1">Индикация <a class="header-anchor" href="#индикация" aria-label="Permalink to &quot;Индикация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Состояние</th><th>Что значит</th><th>Светодиод</th></tr></thead><tbody><tr><td>Запись</td><td>Все подключённые шины передают кадры, потерь нет</td><td>зелёный, мигает медленно</td></tr><tr><td>Тишина на шине</td><td>Одна из шин молчит дольше 2 секунд</td><td>жёлтый, мигает медленно</td></tr><tr><td>Потери</td><td>Кадр потерян или запись на карту не удалась за последние 5 секунд</td><td>красный, мигает часто</td></tr></tbody></table><p>Схемы мигания предварительные и будут уточнены после проверки на машине.</p><h2 id="панель" tabindex="-1">Панель <a class="header-anchor" href="#панель" aria-label="Permalink to &quot;Панель&quot;">​</a></h2><p>Состояние записи, файлы на карте и настройки доступны в браузере, без снятия карты. Для этого регистратор подключается по USB к ноутбуку или к постоянно включённому компьютеру на площадке, на котором работает панель.</p>',14)),i(e,{name:"am_can_logger_dashboard.webp",alt:"Панель регистратора: сессии на карте и графики загрузки шин и карты"}),t[1]||(t[1]=a('<p>Как с ней работать — в <a href="./dashboard">руководстве по панели</a>.</p><h2 id="данные" tabindex="-1">Данные <a class="header-anchor" href="#данные" aria-label="Permalink to &quot;Данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Что</th><th>Где на карте</th><th>Чем читать</th></tr></thead><tbody><tr><td>CAN-кадры</td><td><code>log/&lt;дата&gt;/&lt;время&gt;_can_NNNN.amcan</code></td><td>Панель выгружает их в формате <code>candump</code>; дальше — <code>candump</code>, <code>canplayer</code>, <code>python-can</code>, любой инструмент SocketCAN</td></tr><tr><td>Отметки событий</td><td><code>log/&lt;дата&gt;/&lt;время&gt;_events.log</code></td><td>Любой текстовый редактор</td></tr><tr><td>Вибрации и состояние устройства</td><td><code>log/&lt;дата&gt;/&lt;время&gt;.ulg</code></td><td><code>pyulog</code>, PlotJuggler</td></tr></tbody></table><p>Запись CAN лежит в одной папке с журналом ULog той же сессии и называется по нему; пока часы устройства не выставлены, папка называется <code>sessNNN</code>. Файлы можно забрать без снятия карты — через панель по USB, около 0,5 МБ/с. Беспроводной модуль подходит для проверки состояния, но не для выгрузки больших объёмов. При потоке 3,7 тыс. кадров в секунду запись занимает около 0,2 ГБ в час.</p><h2 id="ограничения-прототипа" tabindex="-1">Ограничения прототипа <a class="header-anchor" href="#ограничения-прототипа" aria-label="Permalink to &quot;Ограничения прототипа&quot;">​</a></h2><ul><li>Две шины CAN на устройство. Для трёх шин нужны два устройства или третий порт через внешний контроллер.</li><li>Гальванической развязки CAN нет.</li><li>Без внешнего источника времени часы устройства после каждого включения начинаются с 2000-01-01, пока их не выставит панель; интервалы между кадрами точные в любом случае. Источник времени выбирается.</li><li>Карта памяти время от времени останавливает запись на несколько секунд для внутреннего обслуживания. Буфер перекрывает такие остановки при умеренном потоке, а самая длинная может стоить пачки кадров: на стенде за 50 часов записи потеряно 0,006 % кадров. От выбора карты это зависит напрямую.</li></ul><h2 id="платформа" tabindex="-1">Платформа <a class="header-anchor" href="#платформа" aria-label="Permalink to &quot;Платформа&quot;">​</a></h2><p>Прототип собран на готовом полётном контроллере класса Pixhawk с нашей прошивкой: так его можно изготовить и проверить в короткие сроки на доступном оборудовании. Подробные характеристики и настройки — в <a href="./datasheet">даташите</a>.</p>',8))])}const b=d(n,[["render",c]]);export{A as __pageData,b as default};
